-- Allow the generic restore successor marker on app_connection_sessions records.
ALTER TABLE public.app_connection_sessions DROP CONSTRAINT IF EXISTS app_connection_sessions_record_identity;
ALTER TABLE public.app_connection_sessions ADD CONSTRAINT app_connection_sessions_record_identity CHECK (

CASE
    WHEN record ? 'credential_repair'::text THEN (public.deft_app_connection_credential_repair_record_valid(record) AND (record ->> 'session_id'::text) = session_id AND ((record ->> 'revision'::text)::integer) = revision AND ((record -> 'scope'::text) ->> 'org_id'::text) = org_id AND ((record -> 'scope'::text) ->> 'owner_user_id'::text) = owner_user_id) IS TRUE
    ELSE (jsonb_typeof(record) = 'object'::text AND record ?& ARRAY['session_id'::text, 'revision'::text, 'scope'::text, 'profile'::text, 'state'::text, 'callback_state_hash'::text, 'callback_consumed'::text, 'callback_expires_at'::text, 'runtime_session_ref'::text, 'account'::text, 'created_at'::text, 'updated_at'::text] AND (record - ARRAY['session_id'::text, 'revision'::text, 'scope'::text, 'profile'::text, 'state'::text, 'callback_state_hash'::text, 'callback_consumed'::text, 'callback_expires_at'::text, 'runtime_session_ref'::text, 'account'::text, 'created_at'::text, 'updated_at'::text, 'action_consent'::text, 'reattachment'::text, 'action_consents'::text, 'upgrade'::text, 'restore'::text]) = '{}'::jsonb AND jsonb_typeof(record -> 'scope'::text) = 'object'::text AND jsonb_typeof(record -> 'profile'::text) = 'object'::text AND (record -> 'scope'::text) ?& ARRAY['org_id'::text, 'owner_user_id'::text] AND (record ->> 'session_id'::text) = session_id AND ((record ->> 'revision'::text)::integer) = revision AND ((record -> 'scope'::text) ->> 'org_id'::text) = org_id AND ((record -> 'scope'::text) ->> 'owner_user_id'::text) = owner_user_id AND (record ->> 'callback_state_hash'::text) ~ '^[a-f0-9]{64}$'::text AND jsonb_typeof(record -> 'callback_consumed'::text) = 'boolean'::text AND (NOT record ? 'action_consent'::text OR jsonb_typeof(record -> 'action_consent'::text) = 'object'::text AND (record -> 'action_consent'::text) ?& ARRAY['action_binding_id'::text, 'action_key'::text, 'authority_epoch'::text, 'consent_id'::text, 'consent_digest'::text, 'expires_at'::text] AND ((record -> 'action_consent'::text) - ARRAY['consent_lifetime'::text, 'action_binding_id'::text, 'action_key'::text, 'authority_epoch'::text, 'consent_id'::text, 'consent_digest'::text, 'expires_at'::text]) = '{}'::jsonb AND ((record -> 'action_consent'::text) ->> 'action_binding_id'::text) ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'::text AND ((record -> 'action_consent'::text) ->> 'consent_id'::text) = ((record -> 'action_consent'::text) ->> 'action_binding_id'::text) AND ((record -> 'action_consent'::text) ->> 'action_key'::text) ~ '^[a-z][a-z0-9_]{0,47}$'::text AND jsonb_typeof((record -> 'action_consent'::text) -> 'authority_epoch'::text) = 'number'::text AND (((record -> 'action_consent'::text) ->> 'authority_epoch'::text)::numeric) >= 0::numeric AND (((record -> 'action_consent'::text) ->> 'authority_epoch'::text)::numeric) <= 2147483647::numeric AND (((record -> 'action_consent'::text) ->> 'authority_epoch'::text)::numeric) = trunc(((record -> 'action_consent'::text) ->> 'authority_epoch'::text)::numeric) AND ((record -> 'action_consent'::text) ->> 'consent_digest'::text) ~ '^sha256:[a-f0-9]{64}$'::text AND public.deft_app_consent_valid(record -> 'action_consent'::text, 'expires_at'::text) AND public.deft_app_consent_deadline(record -> 'action_consent'::text, 'expires_at'::text) <= public.deft_app_consent_deadline(record -> 'scope'::text)) AND (((record ->> 'state'::text) = ANY (ARRAY['starting'::text, 'awaiting_callback'::text, 'connecting'::text, 'checking'::text, 'disconnecting'::text, 'connected'::text, 'not_connected'::text, 'disconnected'::text, 'indeterminate'::text])) OR record ? 'reattachment'::text AND ((record ->> 'state'::text) = ANY (ARRAY['reattach_reviewed'::text, 'reattaching'::text, 'reattach_checking'::text])) OR record ? 'upgrade'::text AND ((record ->> 'state'::text) = ANY (ARRAY['upgrade_reviewed'::text, 'upgrade_starting'::text, 'upgrade_checking'::text]))) AND (NOT record ? 'action_consents'::text OR NOT record ? 'action_consent'::text AND public.deft_app_connection_actions_v2_valid(record -> 'action_consents'::text, record -> 'scope'::text)) AND (NOT record ? 'upgrade'::text OR NOT record ? 'reattachment'::text AND record ? 'action_consents'::text AND public.deft_app_connection_upgrade_valid(record -> 'upgrade'::text, record -> 'scope'::text)) AND public.deft_app_connection_reattachment_valid(record -> 'reattachment'::text, record -> 'scope'::text) AND (NOT record ? 'reattachment'::text OR ((record ->> 'state'::text) <> ALL (ARRAY['awaiting_callback'::text, 'connecting'::text]))))AND (NOT record ? 'restore'::text OR (jsonb_typeof(record -> 'restore'::text) = 'object'::text AND (record -> 'restore'::text) ?& ARRAY['schema_version'::text, 'source'::text] AND ((record -> 'restore'::text) - ARRAY['schema_version'::text, 'source'::text]) = '{}'::jsonb AND (record -> 'restore'::text ->> 'schema_version'::text) = 'deft.app_connection_restore.v1' AND jsonb_typeof((record -> 'restore'::text) -> 'source'::text) = 'object'::text AND ((record -> 'restore'::text) -> 'source'::text) ?& ARRAY['session_id'::text] AND (((record -> 'restore'::text) -> 'source'::text) - ARRAY['session_id'::text]) = '{}'::jsonb AND (((record -> 'restore'::text) -> 'source'::text) ->> 'session_id'::text) ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'::text AND (((record -> 'restore'::text) -> 'source'::text) ->> 'session_id'::text) <> session_id)) IS TRUE
END
);
